const parks=['Magic Kingdom','EPCOT','Hollywood Studios','Animal Kingdom'];
const defaultChecks=['Pack park tickets / passes','Pack chargers','Pack sunscreen','Pack comfortable shoes','Confirm dining plans','Confirm transportation'];
const initial={trips:[],selected:'',data:{},theme:'auto',alerts:[],history:{},images:{},tab:'Home'};
let s=Object.assign(initial,read(KEY,{}));let error='';
let resortFilter='All', resortSearch='', resortDetail=-1, heroIndex=0;
s.gallery ??= {}; s.galleryPrefs ??= {rotation:true, theme:'auto'};
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));error='';tell({kind:'park-saved'});return true}catch(e){error='Storage full or unavailable. Remove an image or export your data.';return false}};
const $=q=>document.querySelector(q),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random();
