const dateAdd=(d,n)=>{let x=new Date(d+'T12:00:00');x.setDate(x.getDate()+n);return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')};
const trip=()=>s.trips.find(t=>t.id===s.selected)||s.trips[0];
function data(){return ensureTrip(trip())}
function importTrips(){const existing=new Set(s.trips.map(t=>t.id));for(const t of original.trips||[])if(t.date&&!existing.has(t.id)){s.trips.push({id:t.id||id(),name:t.name||'Park vacation',date:t.date,endDate:t.endDate||t.date,time:t.time||'15:00',tz:t.tz||''})}if(!s.selected)s.selected=s.trips[0]?.id||'';save()}
if(!embedded&&!s.trips.length)importTrips();
const tabs=['Home','Trips','Explore','Waits','Passport','Memories','Settings'];
let live=[],liveAt=0,liveStatus='Select a configured park to load live waits.',parkId=Object.keys(original.parks||{})[0]||'',loading=false;
function mode(){const t=trip(),d=data();if(!t)return 'Countdown';if(d.mode!=='auto')return d.mode;if(todayOrlando()<t.date)return 'Countdown';if(todayOrlando()===t.date)return 'Travel';if(todayOrlando()<=t.endDate)return 'Vacation';return 'Memories'}
function resort(){return resorts.find(r=>r[0]===data()?.resort)||['Choose your resort','','','#efc987','#304268']}
const safePhoto=v=>typeof v==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(v);
function gallery(r){const list=Array.isArray(s.gallery[r[0]])?s.gallery[r[0]].filter(x=>x&&safePhoto(x.src)):[];const old=s.images[r[0]];return list.length?list:safePhoto(old)?[{src:old,kind:'any',name:'Original photo'}]:[]}
function themePeriod(){let h=Number(new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',hourCycle:'h23'}).format(new Date()));return h>=6&&h<18?'day':'night'}
function galleryFor(r){let all=gallery(r), period=s.galleryPrefs.theme==='auto'?themePeriod():s.galleryPrefs.theme;let preferred=all.filter(x=>x.kind===period||x.kind==='any');return preferred.length?preferred:all}
function bg(r,i=0){let photos=galleryFor(r),photo=photos.length?photos[i%photos.length].src:null;let night=(s.galleryPrefs.theme==='auto'?themePeriod():s.galleryPrefs.theme)==='night';return photo?`linear-gradient(0deg,#10172df5 0%,#10172d38 68%),url(${photo})`:`radial-gradient(ellipse at 78% 14%,${r[3]}${night?'35':'88'},transparent 52%),linear-gradient(145deg,${r[4]},#10172d 88%)`}
function profile(r,i){let p=profiles[i]||['Other','Your own adventure'];return `<div class="profile"><span class="pill">${e(r[1])}</span> <span class="pill">${e(p[0])}</span><h3>${e(p[1])}</h3><p><strong>Transportation:</strong> ${e(r[2])}</p><p class="muted">Check current dining, recreation, transportation and maps with the resort operator.</p><a href="${officialResorts}" target="_blank" rel="noopener">Official resort directory ↗</a></div>`}
function updateHero(){const el=$('#resortHero');if(!el)return;let r=resort();el.style.backgroundImage=bg(r,heroIndex);let cap=$('#photoPosition');if(cap){let n=galleryFor(r).length;cap.textContent=n?`${heroIndex%n+1} / ${n} · ${s.galleryPrefs.theme==='auto'?themePeriod():s.galleryPrefs.theme}`:'Resort color theme · Add photos in Settings'}}
async function resizePhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20000000)throw Error('Choose JPEG, PNG or WebP images under 20 MB.');let url=URL.createObjectURL(file);try{let img=new Image();img.src=url;await img.decode();let c=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(img.naturalWidth,img.naturalHeight));c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));let ctx=c.getContext('2d');ctx.fillStyle='#10172d';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.78)}finally{URL.revokeObjectURL(url)}}
function downloadJSON(obj,name){let blob=new Blob([JSON.stringify(obj)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function count(){const t=trip();if(!t)return [0,0,0,0];let [y,m,d]=t.date.split('-').map(Number),[h,min]=(t.time||'15:00').split(':').map(Number),desired=Date.UTC(y,m-1,d,h,min),target=desired;try{const fmt=new Intl.DateTimeFormat('en-US',{timeZone:t.tz||'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});for(let i=0;i<3;i++){let p=Object.fromEntries(fmt.formatToParts(new Date(target)).map(x=>[x.type,x.value]));let shown=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second);if(shown===desired)break;target+=desired-shown}}catch{target=new Date(t.date+'T'+(t.time||'15:00')).getTime()}let n=Math.max(0,Math.floor((target-Date.now())/1000));return [Math.floor(n/86400),Math.floor(n/3600)%24,Math.floor(n/60)%60,n%60]}
const select=(name,arr,val)=>`<select name="${name}">${arr.map(x=>{let [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${v===val?'selected':''}>${e(l)}</option>`}).join('')}</select>`;
const field=(name,label,type='text',val='',extra='')=>`<label>${e(label)}<input name="${name}" type="${type}" value="${e(val)}" ${extra}></label>`;
const btn=(action,label,extra='')=>`<button data-action="${action}" ${extra}>${label}</button>`;
const form=(action,body,label='Save')=>`<form data-form="${action}">${body}<button class="primary" type="submit">${label}</button></form>`;
