function baseHome(){let t=trip(),d=data(),r=resort();if(!t)return `<section><h2>Your next adventure starts here</h2><p class="muted">Create a trip or import existing Park Day trips in Settings.</p>${btn('tab:Trips','Create a trip','class="primary"')}</section>`;let done=d.checks.filter(x=>x.done).length;let pct=d.checks.length?Math.round(100*done/d.checks.length):0;let next=[...d.milestones].filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date))[0];return `<section id="resortHero" class="hero" style="background-image:${bg(r,heroIndex)}"><p class="eyebrow">${e(mode())} mode · Your next adventure</p><h2>${e(t.name)}</h2><p>${e(r[0])}</p><div class="count" id="count">${count().map((v,i)=>stat(String(v).padStart(2,'0'),['DAYS','HRS','MIN','SEC'][i])).join('')}</div><small>${e(t.date)} — ${e(t.endDate)}</small><div class="hero-tools"><small id="photoPosition"></small><div>${btn('heroPrev','‹','aria-label="Previous photo"')}${btn('heroNext','›','aria-label="Next photo"')}</div></div></section><section><p class="eyebrow">Your resort</p>${profile(r,resorts.indexOf(r))}${btn('tab:Explore','Explore resorts')} ${btn('tab:Settings','Manage photos')}</section><div class="cols"><section><h3>Trip readiness · ${pct}%</h3><progress value="${pct}" max="100"></progress><p>${done} of ${d.checks.length} checklist items</p>${btn('tab:Trips','View trip plan')}</section><section><h3>Next milestone</h3><p>${next?e(next.name)+' · '+e(next.date):'Add a milestone in Trips.'}</p><p class="muted">Dining, packing and check-in reminders</p></section></div><section><h3>Park snapshot</h3><p>${liveAt?e(new Date(liveAt).toLocaleTimeString())+' · '+live.length+' attractions':'Live waits available in the Waits tab. Powered by ThemeParks.wiki.'}</p>${live.filter(x=>x.status==='OPERATING').slice(0,3).map(x=>`<div class="row"><span>${e(x.name)}</span>${e(x.queue?.STANDBY?.waitTime??'—')} min</div>`).join('')}${btn('tab:Waits','Explore live waits')}</section><section><h3>Daily magic</h3><p>${['Choose one new attraction to try.','Make time to explore your resort.','Take a photo in a favorite spot.','Leave room for an unexpected adventure.'][new Date().getDate()%4]}</p></section>`}
function baseTrips(){let t=trip(),d=data();return `<section><h2>Trips</h2>${s.trips.length?select('trip',s.trips.map(x=>[x.id,x.name]),t.id):''}<details ${!t?'open':''}><summary>Add a trip</summary>${form('newTrip',field('name','Trip name','text','','required')+field('date','Arrival','date',today(),'required')+field('end','Departure','date',today(),'required')+field('time','Check-in time','time','15:00'),'Create trip')}</details></section>`+(t?`<section><h3>Trip settings</h3>${form('editTrip',field('name','Trip name','text',t.name,'required')+field('date','Arrival','date',t.date,'required')+field('end','Departure','date',t.endDate,'required')+field('time','Check-in','time',t.time)+`<label>Resort</label>${select('resort',[['','Choose a resort'],...resorts.map(r=>r[0])],d.resort)}<label>Vacation mode</label>${select('mode',['auto','Countdown','Travel','Vacation','Memories'],d.mode)}`)}</section><section><h3>Daily itinerary</h3>${form('plan',field('date','Day','date',t.date,`min="${e(t.date)}" max="${e(t.endDate)}" required`)+field('time','Time','time','09:00')+`<label>Location</label>${select('park',['Resort',...parks,'Other'],'Resort')}`+field('name','Activity','text','','required'),'Add activity')}${[...d.plans].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(x=>`<div class="row"><span>${e(x.date)} · ${e(x.time)}<br>${e(x.name)} <small>${e(x.park)}</small></span>${btn('remove:plans:'+x.id,'Remove')}</div>`).join('')}</section><section><h3>Milestones</h3>${form('milestone',field('name','Reminder','text','','required')+field('date','Date','date',t.date,'required'),'Add milestone')}${d.milestones.map(x=>`<div class="row"><label><input type="checkbox" data-toggle="milestones:${x.id}" ${x.done?'checked':''}> ${e(x.name)} · ${e(x.date)}</label>${btn('remove:milestones:'+x.id,'×')}</div>`).join('')}</section><section><h3>Packing & preparation</h3>${d.checks.map((x,i)=>`<div class="row"><label><input type="checkbox" data-toggle="checks:${i}" ${x.done?'checked':''}> ${e(x.name)}</label>${btn('remove:checks:'+i,'×')}</div>`).join('')}${form('check',field('name','New checklist item','text','','required'),'Add item')}</section><section><h3>Vacation budget</h3>${form('budget',field('budget','Total budget ($)','number',d.budget,'min="0" step="0.01" required'))}<div class="grid">${stat(money(d.expenses.reduce((a,x)=>a+x.amount,0)),'Spent')}${stat(money(d.budget-d.expenses.reduce((a,x)=>a+x.amount,0)),'Remaining')}</div>${form('expense',field('name','Expense','text','','required')+field('amount','Amount ($)','number','','min="0.01" step="0.01" required'),'Add expense')}${d.expenses.map(x=>`<div class="row"><span>${e(x.name)} · ${money(x.amount)}</span>${btn('remove:expenses:'+x.id,'×')}</div>`).join('')}</section>`:'')}
function explore(){let shown=resorts.map((r,i)=>({r,i})).filter(({r,i})=>(resortFilter==='All'||r[1]===resortFilter)&&[...r.slice(0,3),...profiles[i]].join(' ').toLowerCase().includes(resortSearch.toLowerCase()));let r=resorts[resortDetail];return `<section><h2>Explore resorts</h2><p class="muted">Find your next stay by name, hotel category or transportation.</p>${form('resortSearch',field('query','Search resorts','search',resortSearch)+`<label>Category</label>${select('category',['All',...new Set(resorts.map(r=>r[1]))],resortFilter)}`,'Search / filter')}${btn('clearFilter','Clear filters')}<p class="muted">${shown.length} resorts</p></section>${r?`<section><div class="resort large" style="background-image:${bg(r)}">${e(r[0])}</div>${profile(r,resortDetail)}<p>${gallery(r).length} personal photos</p>${trip()?btn('resort:'+resortDetail,'Use for this trip','class="primary"'):''} ${btn('detailClose','Close profile')}</section>`:''}<section><div class="grid resort-grid">${shown.map(({r,i})=>`<div class="resort-card"><button class="resort" data-action="detail:${i}" style="background-image:${bg(r)}">${e(r[0])}</button><small>${e(r[1])} · ${e(r[2])}</small><p>${gallery(r).length} photos</p>${btn('detail:'+i,'Details')}${trip()?btn('resort:'+i,data().resort===r[0]?'Selected':'Select',data().resort===r[0]?'class="active"':''):''}</div>`).join('')||'<p>No matching resorts.</p>'}</div></section><section><h3>Maps and walking</h3><p>The original Map tab in this integrated preview provides park maps and GPS tracking. Production data on another domain does not transfer automatically.</p><a href="${originalURL}">Open original Home and Map tabs ↗</a></section>`}
function basePassport(){let d=data();if(!d)return '<section>Create a trip to log rides.</section>';let unique=new Set(d.rides.map(x=>x.park+'|'+x.name.toLowerCase()));return `<section><h2>Attraction passport</h2><div class="grid">${stat(d.rides.length,'Rides logged')}${stat(unique.size,'Unique attractions')}${stat(new Set(d.rides.map(x=>x.park)).size,'Parks explored')}${stat(miles(),'Miles walked')}</div>${form('ride',`<label>Park</label>${select('park',[...parks,'Other'],parks[0])}`+field('name','Attraction','text','','required')+field('wait','Actual wait (minutes)','number',0,'min="0" step="1" required'),'Log attraction')}${d.rides.map(x=>`<div class="row"><span>${e(x.name)}<br><small>${e(x.park)} · ${x.wait} min</small></span>${btn('remove:rides:'+x.id,'×')}</div>`).join('')}</section><section><h3>Achievements</h3>${[['First ride',d.rides.length>=1],['Ride fan',d.rides.length>=10],['Explorer',unique.size>=20],['Four parks',parks.every(p=>d.rides.some(r=>r.park===p))],['Walking marathon',Number(miles())>=26.2]].map(([n,b])=>`<div class="row"><span>${e(n)}</span><span class="pill">${b?'Unlocked':'Locked'}</span></div>`).join('')}</section>`}
function baseMemories(){let t=trip(),d=data();if(!t)return '<section>Create a trip to start your memories.</section>';let counts={};d.rides.forEach(r=>counts[r.name]=(counts[r.name]||0)+1);let fav=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];return `<section><p class="eyebrow">Vacation in review</p><h2>${e(t.name)}</h2><div class="grid">${stat(d.rides.length,'Rides')}${stat(miles(),'Miles walked')}${stat(d.rides.reduce((a,x)=>a+x.wait,0),'Queue minutes')}${stat(new Set(d.rides.map(x=>x.park)).size,'Parks')}</div><p>Most ridden: ${fav?e(fav[0])+' · '+fav[1]+' times':'No rides logged'}</p>${btn('share','Share recap')}</section><section><h3>Trip journal</h3>${form('journal',field('date','Date','date',today(),'required')+field('note','Memory','text','','required'),'Save memory')}${d.journal.map(x=>`<div class="row"><span>${e(x.date)} · ${e(x.note)}</span>${btn('remove:journal:'+x.id,'×')}</div>`).join('')}</section>`}
function baseSettings(){let r=resort();return `<section><h2>Settings</h2><p>V2 data remains separate from production.</p>${btn('import','Import existing trips (same origin)')} ${btn('export','Export V2 backup')}<h3 style="margin-top:20px">Resort photo gallery</h3><p class="muted">Upload your own licensed photos. Photos are compressed and kept on this device; storage capacity varies. Existing single photos are preserved.</p>${form('galleryUpload',`<label>Resort</label>${select('resort',resorts.map(r=>r[0]),r[0])}<label>Photo type</label>${select('kind',[['any','Any time'],['day','Daytime'],['night','Nighttime']],'any')}<label>Photos<input type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple required></label>`,'Add photos')}${form('galleryPrefs',`<label>Theme</label>${select('theme',[['auto','Automatic (Orlando time)'],['day','Day'],['night','Night']],s.galleryPrefs.theme)}<label><input type="checkbox" name="rotation" ${s.galleryPrefs.rotation?'checked':''}> Rotate photos every 15 seconds</label>`,'Save gallery preferences')}${btn('galleryExport','Export resort picture pack')} ${form('galleryImport','<label>Import picture pack (.json)<input type="file" name="pack" accept="application/json,.json" required></label>','Import pack')}</section><section><h3>Saved photos</h3>${resorts.map((r,i)=>{let list=gallery(r);return list.length?`<details><summary>${e(r[0])} · ${list.length} photos</summary><div class="grid">${list.map((x,j)=>`<div><img class="gallery-thumb" src="${x.src}" alt="${e(x.name||r[0])}"><small>${e(x.kind)}</small>${btn('galleryRemove:'+i+':'+j,'Remove')}</div>`).join('')}</div></details>`:''}).join('')||'<p>No saved photos yet.</p>'}</section><section><h3>Native iOS roadmap</h3><p>Widgets, Live Activities, HealthKit, iCloud and Apple Watch remain planned native features.</p></section>`}
