const todayOrlando=()=>{let p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:trip()?.tz||'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`}

