function ensureTrip(t){if(!t)return null;let d=s.data[t.id]??={};for(const [k,v] of Object.entries({resort:'',plans:[],checks:defaultChecks.map(name=>({name,done:false})),budget:0,expenses:[],rides:[],journal:[],milestones:[],mode:'auto',walking:{},wish:[],dayParks:{}})){if(d[k]==null)d[k]=v}return d}
const dayRange=t=>{let days=[];if(!t?.date)return days;for(let d=t.date;d<=(t.endDate||t.date)&&days.length<366;d=dateAdd(d,1))days.push(d);return days};
const prettyDate=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
const timeDisplay=x=>{if(!x)return '—';const d=new Date(x);return Number.isNaN(+d)?'—':new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'}).format(d)};
const currentPlanDay=()=>{const t=trip();if(!t)return '';return dayRange(t).includes(planDay)?planDay:(todayOrlando()>=t.date&&todayOrlando()<=t.endDate?todayOrlando():t.date)};
const nextPlans=()=>{let d=data();return (d?.plans||[]).filter(x=>!x.done&&x.date>=todayOrlando()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))};
function reminders(d){return (d?.milestones||[]).filter(x=>!x.done&&x.date<=todayOrlando()).sort((a,b)=>a.date.localeCompare(b.date))}
function tripStats(t){let d=ensureTrip(t),rides=d?.rides||[],counts=new Map();for(const r of rides){let k=r.park+'|'+r.name.toLowerCase(),v=counts.get(k)||{name:r.name,count:0};v.count++;counts.set(k,v)}let walkingMiles=tripMiles(t);return {rides:rides.length,unique:counts.size,parks:new Set(rides.map(r=>r.park)).size,wait:rides.reduce((a,r)=>a+(Number(r.wait)||0),0),miles:walkingMiles,spent:(d?.expenses||[]).reduce((a,x)=>a+(Number(x.amount)||0),0),favorite:[...counts.values()].sort((a,b)=>b.count-a.count)[0]}}
function tripMiles(t){let d=ensureTrip(t);if(!d)return '0.0';let sum=0;for(const day of dayRange(t)){if(Object.hasOwn(d.walking,day)){sum+=Number(d.walking[day])||0;continue}const h=Object.entries(walking.health||{}).filter(([k])=>k.startsWith(day)),g=Object.entries(walking.gps||{}).filter(([k])=>k.startsWith(day));sum+=(h.length?h:g).reduce((a,[,v])=>a+(Number(v)||0),0)/1609.344}return sum.toFixed(1)}
function dashboard(){let t=trip(),d=data();if(!t)return baseHome();let st=tripStats(t),m=mode(),next=nextPlans()[0],due=reminders(d),days=dayRange(t),day=days.indexOf(todayOrlando())+1;let summary=m==='Countdown'?`<p>Get ready for your ${days.length}-day adventure. ${due.length?due.length+' reminder(s) due.':'No reminders due.'}</p>`:m==='Travel'?'<p>Arrival day! Check your transportation, check-in and first-day plans.</p>':m==='Vacation'?`<p>Day ${day||'—'} of ${days.length} · Make the most of your park day.</p>`:'<p>Relive your trip, review your stats and share your memories.</p>';let actions=m==='Memories'?btn('tab:Memories','View vacation recap','class="primary"'):m==='Vacation'?btn('tab:Waits','Live park waits','class="primary"')+btn('tab:Passport','Log an attraction'):btn('tab:Trips','Open trip planner','class="primary"');return (m==='Memories'||m==='Vacation'?baseHome().replace(/<div class="count" id="count">[\s\S]*?<\/div><small>/,`<p class="active-trip-label">${m==='Memories'?'Your adventure, remembered':'Your adventure is underway'}</p><small>`):baseHome()).replace('<div class="cols">',`<section class="mode-panel"><p class="eyebrow">${e(m)} mode</p>${summary}<div class="actions">${actions}</div><div class="grid">${stat(st.rides,'Rides')}${stat(st.miles,'Miles')}${stat(money(st.spent),'Spent')}</div>${next?`<p class="next-item"><b>Up next</b> · ${e(prettyDate(next.date))} ${e(next.time)} · ${e(next.name)}</p>`:''}${due.slice(0,3).map(x=>`<p class="due">Reminder: ${e(x.name)} · ${e(x.date)}</p>`).join('')}</section><div class="cols">`)}
function planner(){let t=trip(),d=data(),html=baseTrips();if(embedded){const start=`<section><h2>Detailed planner</h2><p class="muted">Trip dates, destinations and park days come from your original trip calendar.</p>${s.trips.length?select('trip',s.trips.map(x=>[x.id,x.name]),t.id):''}${btn('originalTrips','Open original Trips','class="primary"')}</section>`;if(!t)return start;html=start+`<section><h3>Resort hotel & vacation mode</h3>${form('integratedPrefs',`<label>Resort hotel</label>${select('resort',[['','Choose a resort'],...resorts.map(r=>r[0])],d.resort)}<label>Vacation mode</label>${select('mode',['auto','Countdown','Travel','Vacation','Memories'],d.mode)}`)}</section>`+html.slice(html.indexOf('<section><h3>Daily itinerary</h3>'));}if(!t)return html;let day=currentPlanDay(),days=dayRange(t),plans=d.plans.filter(x=>x.date===day).sort((a,b)=>a.time.localeCompare(b.time)),edit=d.plans.find(x=>x.id===editPlanId),dayPark=embedded?(originalDayParks(t,day)[0]||'Resort'):(d.dayParks[day]||'Resort');let dayControl=`<label>Trip day</label>${select('p7day',days.map((x,i)=>[x,`Day ${i+1} · ${prettyDate(x)}`]),day)}`;let timeline=`<section><h3>Daily itinerary</h3>${dayControl}<div class="actions">${btn('p7prev','← Previous day',day===days[0]?'disabled':'')}${btn('p7next','Next day →',day===days.at(-1)?'disabled':'')}</div>${embedded?`<p><b>Original park plan:</b> ${e(originalDayParks(t,day).join(' · ')||'Not planned')}</p>${btn('originalDay','Edit parks in original calendar')}`:form('p7dayPark',`<label>Day destination</label>${select('park',['Resort',...parks,'Other'],dayPark)}`,'Set day destination')}<p class="muted">${plans.filter(x=>x.done).length} of ${plans.length} activities completed</p>${plans.map(x=>`<div class="row timeline"><label><input type="checkbox" data-toggle="plans:${e(x.id)}" ${x.done?'checked':''}> <b>${e(x.time)}</b> · ${e(x.name)}<br><small>${e(x.park)} · ${e(x.kind||'Activity')}${x.note?' · '+e(x.note):''}</small></label><div>${btn('p7editPlan:'+x.id,'Edit')} ${btn('remove:plans:'+x.id,'×','aria-label="Remove activity"')}</div></div>`).join('')||'<p>No activities planned for this day.</p>'}${form('p7plan',`<input type="hidden" name="id" value="${e(edit?.id||'')}">`+field('date','Date','date',edit?.date||day,`min="${e(t.date)}" max="${e(t.endDate)}" required`)+field('time','Time','time',edit?.time||'09:00','required')+`<label>Location</label>${select('park',[...new Set(['Resort',...parks,...originalDayParks(t,day),'Other',...(edit?.park?[edit.park]:[])])],edit?.park||dayPark)}<label>Type</label>${select('kind',['Activity','Attraction','Dining','Show','Transportation','Break','Check-in'],edit?.kind||'Activity')}`+field('name','Activity','text',edit?.name||'','required maxlength="160"')+field('note','Notes / reservation reference','text',edit?.note||'','maxlength="250"'),edit?'Update activity':'Add activity')}${edit?btn('p7cancelPlan','Cancel edit'):''}<div class="actions">${btn('p7template','Add sample park-day plan')}${btn('p7calendar','Export itinerary calendar (.ics)')}</div><small>Sample plans are editable suggestions, not reservations or verified showtimes.</small></section>`;
html=html.replace(/<section><h3>Daily itinerary<\/h3>[\s\S]*?<\/section>/,()=>timeline);html=html.replace('<section><h3>Milestones</h3>',`<section><h3>Milestones & reminders</h3><p class="muted">${reminders(d).length} due or overdue · reminders appear in the app, calendar export works outside it.</p>${btn('p7milestones','Add suggested preparation milestones')}`);return html+`<section><h3>Walking log</h3><p class="muted">Record distance from your phone or watch. Manual daily entries override any imported daily total to avoid double-counting.</p>${form('p7walk',field('date','Day','date',day,`min="${e(t.date)}" max="${e(t.endDate)}" required`)+field('miles','Miles walked','number',d.walking[day]??0,'min="0" max="100" step="0.01" required'),'Save daily miles')}${Object.entries(d.walking).sort().map(([date,v])=>`<div class="row"><span>${e(date)} · ${e(v)} mi</span>${btn('p7removeWalk:'+date,'Remove')}</div>`).join('')}</section>`}
async function apiGet(path){let r=await fetch(API+path,{signal:AbortSignal.timeout(15000)});if(!r.ok){let err=Error('HTTP '+r.status);if(r.status===429)err.retry=Math.max(60,Number(r.headers.get('Retry-After'))||60);throw err}return r.json()}
async function discoverParks(){directoryStatus='Loading park directory…';render();try{let j=await apiGet('/destinations'),dest=(j.destinations||[]).find(x=>/walt disney world/i.test(x.name));if(!dest?.parks?.length)throw Error('Walt Disney World directory unavailable');for(const p of dest.parks)if(p.id&&p.name)s.parkDirectory[p.id]={name:parkName(p.name)};save();directoryStatus='Park directory updated.'}catch(err){directoryStatus='Unable to load park directory: '+err.message}if(s.tab==='Waits')render()}
function choosePark(v){if(!v)return;parkId=v;s.lastPark=v;live=[];shows=[];schedule=[];scheduleStatus='';liveAt=0;save();fetchWaits()}
async function fetchParkData(){if(!parkId||loading)return;if(Date.now()<waitRetryAt){liveStatus='Provider rate limit. Try again later.';render();return}let selected=parkId,request=++liveRequest;loading=true;liveStatus='Loading live data…';if(s.tab==='Waits'||s.tab==='Home')render();const path='/entity/'+encodeURIComponent(selected);try{let j=await apiGet(path+'/live');if(selected!==parkId||request!==liveRequest)return;live=(j.liveData||[]).filter(x=>x.entityType==='ATTRACTION');shows=(j.liveData||[]).filter(x=>x.entityType==='SHOW');liveAt=Date.now();liveStatus='Updated '+new Date(liveAt).toLocaleTimeString();for(const x of live){let w=x.queue?.STANDBY?.waitTime,previous=s.parkStatuses[x.id];if(typeof w==='number'&&x.status==='OPERATING'){let h=s.history[x.id]??=[];if(!h.length||liveAt-h.at(-1).at>=60000){h.push({at:liveAt,w});s.history[x.id]=h.slice(-72)}}for(const a of s.alerts.filter(a=>a.ride===x.id)){let hit=a.type==='reopen'?x.status==='OPERATING'&&previous&&previous!=='OPERATING':x.status==='OPERATING'&&typeof w==='number'&&w<=a.limit;if(hit&&!a.hit){let msg=a.type==='reopen'?x.name+' reopened':x.name+' · '+w+' minute standby wait';s.activity.unshift({name:msg,at:liveAt});s.activity=s.activity.slice(0,50);if(globalThis.Notification?.permission==='granted'){try{let reg=await navigator.serviceWorker?.getRegistration();if(reg)await reg.showNotification(msg);else new Notification(msg)}catch{}}}a.hit=Boolean(hit)}s.parkStatuses[x.id]=x.status}save()}catch(err){if(err.retry)waitRetryAt=Date.now()+err.retry*1000;if(selected===parkId)liveStatus='Unable to refresh live waits: '+err.message+(liveAt?' · showing previous sample':'')}finally{loading=false;if(selected!==parkId){fetchParkData();return}if(s.tab==='Waits'||s.tab==='Home')render()}}
async function loadSchedule(){const selected=parkId; scheduleStatus='Loading park hours…';render();try{let j=await apiGet('/entity/'+encodeURIComponent(selected)+'/schedule');if(selected!==parkId)return;schedule=j.schedule||[];scheduleStatus=schedule.length?'Published park hours · Orlando time':'No published hours returned.'}catch(err){if(selected!==parkId)return;scheduleStatus='Park hours unavailable: '+err.message}if(s.tab==='Waits')render()}
async function loadCatalog(){const selected=parkId;directoryStatus='Loading attraction catalog…';render();try{let j=await apiGet('/entity/'+encodeURIComponent(selected)+'/children');s.catalog[parkList().find(x=>x[0]===selected)?.[1]||selected]=(j.children||[]).filter(x=>x.entityType==='ATTRACTION'&&x.name).map(x=>({id:x.id,name:x.name}));save();directoryStatus='Attraction catalog updated.'}catch(err){directoryStatus='Catalog unavailable: '+err.message}if(s.tab==='Waits'||s.tab==='Passport')render()}
function liveScreen(){let list=parkList(),favs=s.favorites[parkId]||[],filtered=live.map((x,i)=>({x,i})).filter(({x})=>x.name.toLowerCase().includes(waitQuery.toLowerCase())&&(waitFilter==='All'||waitFilter==='Favorites'&&favs.includes(x.id)||waitFilter==='Operating'&&x.status==='OPERATING'||waitFilter==='Closed / down'&&x.status!=='OPERATING'));filtered.sort((a,b)=>waitSort==='Name'?a.x.name.localeCompare(b.x.name):waitSort==='Longest wait'?(b.x.status==='OPERATING'?(b.x.queue?.STANDBY?.waitTime??-1):-1)-(a.x.status==='OPERATING'?(a.x.queue?.STANDBY?.waitTime??-1):-1):(a.x.status==='OPERATING'?(a.x.queue?.STANDBY?.waitTime??Infinity):Infinity)-(b.x.status==='OPERATING'?(b.x.queue?.STANDBY?.waitTime??Infinity):Infinity));const entries=filtered.map(({x,i})=>{let w=x.queue?.STANDBY?.waitTime,h=s.history[x.id]||[],trend=h.length>1?h.at(-1).w-h.at(-2).w:0;return `<details><summary>${e(x.name)} · ${x.status==='OPERATING'&&typeof w==='number'?w+' min':e(x.status||'No status')} ${trend>0?'↑':trend<0?'↓':''}</summary><div class="actions">${btn('p7fav:'+i,favs.includes(x.id)?'★ Favorited':'☆ Favorite')}${trip()?btn('p7log:'+i,'Log ride'):''}${btn('p7reopen:'+i,'Watch reopening')}</div>${h.length?`<div class="chart" aria-label="Recent local wait samples">${h.map(v=>`<i title="${v.w} min" style="height:${Math.max(2,v.w/Math.max(1,...h.map(p=>p.w))*100)}%"></i>`).join('')}</div><small>${h.length} local samples · latest ${e(new Date(h.at(-1).at).toLocaleTimeString())}</small>`:''}${form('alert',`<input type="hidden" name="ride" value="${e(x.id)}"><input type="hidden" name="name" value="${e(x.name)}">`+field('limit','Alert at or below (min)','number',20,'min="0" required'),'Set wait alert')}</details>`}).join('');let open=live.filter(x=>x.status==='OPERATING'&&Number.isFinite(x.queue?.STANDBY?.waitTime)).sort((a,b)=>a.queue.STANDBY.waitTime-b.queue.STANDBY.waitTime).slice(0,3);return `<section><h2>Live park dashboard</h2><p class="muted">Powered by <a href="https://www.themeparks.wiki/">ThemeParks.wiki</a> · refreshes while the app is open.</p>${select('p7park',list,parkId)}<div class="actions">${btn('p7discover','Find Disney World parks')}${btn('refresh','Refresh waits')}${btn('p7schedule','Load park hours')}${btn('p7catalog','Load ride catalog')}</div><p role="status">${e(liveStatus)}</p><small>${e(directoryStatus)}</small>${form('p7waitFilter',field('query','Search attractions','search',waitQuery)+`<label>Filter</label>${select('filter',['All','Favorites','Operating','Closed / down'],waitFilter)}<label>Sort</label>${select('sort',['Shortest wait','Longest wait','Name'],waitSort)}`,'Apply filters')}<p>${filtered.length} attractions shown</p></section><section><h3>Shortest posted waits</h3>${open.map(x=>`<div class="row"><span>${e(x.name)}</span><b>${x.queue.STANDBY.waitTime} min</b></div>`).join('')||'<p>No operating attractions with a posted wait.</p>'}<small>Not a route or wait prediction.</small></section><section><h3>Attractions</h3>${entries||'<p>No matching live entries. Refresh or change filters.</p>'}</section><section><h3>Park hours</h3><p>${e(scheduleStatus||'Load published hours for this park.')}</p>${schedule.filter(x=>x.date>=todayOrlando()).slice(0,14).map(x=>`<div class="row"><span>${e(x.date)} · ${e(x.type||'Hours')}</span>${e(timeDisplay(x.openingTime))} – ${e(timeDisplay(x.closingTime))}</div>`).join('')}</section><section><h3>Showtimes</h3>${shows.map(x=>`<div class="row"><span>${e(x.name)}<br><small>${e(x.status||'')}</small></span>${e((x.showtimes||[]).filter(z=>z.startTime&&new Date(z.startTime)>=new Date()).slice(0,4).map(z=>timeDisplay(z.startTime)).join(' · ')||'No upcoming times supplied')}</div>`).join('')||'<p>No shows returned by the provider.</p>'}</section><section><h3>Watch list</h3>${s.alerts.map((a,i)=>`<div class="row"><span>${e(a.name)} · ${a.type==='reopen'?'Reopening':e(a.limit)+' min or less'} ${a.hit?'· triggered':''}</span>${btn('alertRemove:'+i,'×')}</div>`).join('')||'<p>No alerts yet.</p>'}${btn('notify','Enable browser notifications')}<p class="muted">Foreground checks only; background push requires a server.</p><h3>Recent alerts</h3>${s.activity.slice(0,10).map(x=>`<p>${e(new Date(x.at).toLocaleString())} · ${e(x.name)}</p>`).join('')||'<p>No alerts triggered yet.</p>'}</section>`}
function passport7(){let d=data();if(!d)return basePassport();let t=trip(),st=tripStats(t),all=s.trips.flatMap(t=>ensureTrip(t).rides),visited=new Set(all.map(x=>x.park+'|'+x.name.toLowerCase())),cats=Object.entries(s.catalog).filter(([p])=>passportPark==='All'||p===passportPark);let progress=cats.map(([p,items])=>{let done=items.filter(x=>visited.has(p+'|'+x.name.toLowerCase())).length;return `<div class="passport-progress"><b>${e(p)}</b><p>${done} of ${items.length} catalog attractions logged across all trips</p><progress value="${done}" max="${Math.max(1,items.length)}"></progress></div>`}).join('');let wishlist=d.wish.filter(x=>passportPark==='All'||x.park===passportPark);let achievements=[['First adventure',all.length>=1],['Ride enthusiast',all.length>=25],['Century club',all.length>=100],['Four park explorer',parks.every(p=>all.some(r=>r.park===p))],['Twenty unique attractions',visited.size>=20],['Repeat visitor',s.trips.filter(t=>ensureTrip(t).rides.length).length>=2],['Resort explorer',new Set(s.trips.map(t=>ensureTrip(t).resort).filter(Boolean)).size>=3],['Marathon trip',Number(st.miles)>=26.2],['Night owl',all.some(r=>r.time&&r.time>='21:00')]];return `<section><h2>Ride passport</h2><div class="grid">${stat(st.rides,'Trip rides')}${stat(st.unique,'Trip unique')}${stat(all.length,'Lifetime rides')}${stat(visited.size,'Lifetime unique')}</div><p>${e(t.name)}</p>${form('p7passportFilter',`<label>Park</label>${select('park',['All',...parks,...Object.keys(s.catalog).filter(p=>!parks.includes(p))],passportPark)}`,'Filter passport')}${progress||'<p>Load a ride catalog from the Waits screen for park completion percentages.</p>'}${btn('tab:Waits','Find attraction catalogs')}</section><section><h3>Log an attraction</h3>${rideForm()}</section><section><h3>Attraction wish list</h3>${form('p7wish',`<label>Park</label>${select('park',[...parks,'Other'],passportPark==='All'?'Magic Kingdom':passportPark)}`+field('name','Attraction','text','','required maxlength="150"'),'Add to wish list')}${wishlist.map(x=>`<div class="row"><span>${e(x.name)} · ${e(x.park)}</span>${btn('p7wishLog:'+x.id,'Log ride')}${btn('remove:wish:'+x.id,'×')}</div>`).join('')||'<p>No wish list entries.</p>'}${cats.map(([p,items])=>`<details><summary>${e(p)} catalog · ${items.length} rides</summary>${items.map((x,i)=>`<div class="row"><span>${visited.has(p+'|'+x.name.toLowerCase())?'✓ ':''}${e(x.name)}</span><button data-p7-catalog-park="${e(p)}" data-p7-catalog-i="${i}">Log</button></div>`).join('')}</details>`).join('')}</section><section><h3>Trip ride history</h3>${d.rides.filter(x=>passportPark==='All'||x.park===passportPark).slice().reverse().map(x=>`<div class="row"><span>${e(x.name)}<br><small>${e(x.park)} · ${e(x.date)} · ${x.wait==null?'Wait not recorded':e(x.wait)+' min'}</small></span>${btn('p7editRide:'+x.id,'Edit')}${btn('remove:rides:'+x.id,'×')}</div>`).join('')||'<p>No logged attractions.</p>'}</section><section><h3>Lifetime achievements</h3><div class="achievement-grid">${achievements.map(([n,b])=>`<div class="achievement ${b?'earned':''}"><b>${b?'★':'☆'}</b><span>${e(n)}</span><small>${b?'Unlocked':'Locked'}</small></div>`).join('')}</div></section>`}
let rideDraft=null;
function rideForm(){let d=data(),t=trip(),r=d.rides.find(x=>x.id===editingRide)||rideDraft||{};return form('p7ride',`<input type="hidden" name="id" value="${e(editingRide)}"><label>Park</label>${select('park',[...new Set([...parks,'Other',r.park].filter(Boolean))],r.park||'Magic Kingdom')}`+field('name','Attraction','text',r.name||'','required maxlength="160"')+field('date','Ride date','date',r.date||(todayOrlando()>=t.date&&todayOrlando()<=t.endDate?todayOrlando():t.date),`min="${e(t.date)}" max="${e(t.endDate)}" required`)+field('time','Ride time (optional)','time',r.time||'')+field('wait','Actual wait (optional, minutes)','number',r.wait??'','min="0" max="1440" step="1"'),editingRide?'Update ride':'Log ride')+(editingRide||rideDraft?btn('p7cancelRide','Cancel'): '')}
function prepRide(r){rideDraft={name:r.name,park:r.park};editingRide='';s.tab='Passport';change();window.scrollTo(0,0)}
function recapText(t){let a=tripStats(t);return `${t.name} · ${t.date} to ${t.endDate}\n${a.rides} rides · ${a.unique} unique attractions · ${a.parks} parks\n${a.miles} miles walked · ${a.wait} recorded queue minutes\nFavorite attraction: ${a.favorite?a.favorite.name+' ('+a.favorite.count+' rides)':'Not recorded'}`}
async function shareRecap(){let txt=recapText(trip());try{if(navigator.share)await navigator.share({text:txt});else if(navigator.clipboard){await navigator.clipboard.writeText(txt);alert('Recap copied.')}else alert(txt)}catch(e){if(e.name!=='AbortError')alert('Sharing unavailable.')}}
async function recapImage(){let t=trip(),a=tripStats(t),r=resort(),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;let ctx=canvas.getContext('2d');let g=ctx.createLinearGradient(0,0,1080,1350);g.addColorStop(0,r[4]);g.addColorStop(1,'#10172d');ctx.fillStyle=g;ctx.fillRect(0,0,1080,1350);const put=(v,x,y,size,color='#ffffff',max=930)=>{ctx.fillStyle=color;ctx.font=`${size>=50?'bold ':''}${size}px system-ui`;ctx.fillText(String(v),x,y,max)};put('PARK DAY · VACATION RECAP',75,100,36,r[3]);put(t.name,75,230,72);put(`${t.date} — ${t.endDate}`,75,300,35,'#d2dbeb');put(r[0],75,360,37);let cells=[[a.rides,'RIDES'],[a.unique,'UNIQUE ATTRACTIONS'],[a.parks,'PARKS'],[a.miles,'MILES WALKED'],[a.wait,'RECORDED QUEUE MIN'],[dayRange(t).length,'VACATION DAYS']];for(let i=0;i<cells.length;i++){let x=75+(i%2)*475,y=440+Math.floor(i/2)*210;ctx.fillStyle='#10172dbb';ctx.fillRect(x,y,450,175);put(cells[i][0],x+25,y+85,70,r[3],400);put(cells[i][1],x+25,y+130,26,'#d2dbeb',400)}put('MOST RIDDEN',75,1160,30,r[3]);put(a.favorite?a.favorite.name:'Not recorded',75,1235,50);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)return;let file=new File([blob],'park-day-recap.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Vacation recap'});return}catch(err){if(err.name==='AbortError')return}}downloadBlob(blob,'park-day-recap.png')}
function downloadBlob(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function memories7(){let t=trip(),d=data();if(!t)return baseMemories();let st=tripStats(t),other=s.trips.find(x=>x.id===historyCompare),history=s.trips.slice().sort((a,b)=>b.date.localeCompare(a.date));return `<section class="recap" style="background-image:${bg(resort())}"><p class="eyebrow">Vacation in review</p><h2>${e(t.name)}</h2><p>${e(t.date)} — ${e(t.endDate)} · ${e(resort()[0])}</p><div class="grid">${stat(st.rides,'Rides')}${stat(st.unique,'Unique attractions')}${stat(st.miles,'Miles walked')}${stat(st.wait,'Recorded queue minutes')}${stat(st.parks,'Parks')}${stat(money(st.spent),'Tracked spending')}</div><h3>Most ridden: ${e(st.favorite?.name||'Not recorded')}${st.favorite?' · '+st.favorite.count+' rides':''}</h3><div class="actions">${btn('p7share','Share text recap','class="primary"')}${btn('p7recapImage','Share / save recap image')}</div></section><section><h3>Vacation history</h3>${history.map(x=>{let a=tripStats(x);return `<div class="row"><span><b>${e(x.name)}</b><br><small>${e(x.date)} · ${a.rides} rides · ${a.miles} mi</small></span><button data-p7-trip="${e(x.id)}">${x.id===t.id?'Current':'Open'}</button></div>`}).join('')}${form('p7compare',`<label>Compare another trip</label>${select('tripId',[['','Choose trip'],...history.filter(x=>x.id!==t.id).map(x=>[x.id,x.name])],historyCompare)}`,'Compare')}${other?`<div class="comparison"><table><thead><tr><th>Metric</th><th>${e(t.name)}</th><th>${e(other.name)}</th></tr></thead><tbody>${[['Rides','rides'],['Unique','unique'],['Miles','miles'],['Queue minutes','wait'],['Parks','parks']].map(([n,k])=>`<tr><td>${n}</td><td>${e(st[k])}</td><td>${e(tripStats(other)[k])}</td></tr>`).join('')}</tbody></table></div>`:''}</section><section><h3>Trip journal</h3>${form('p7journal',field('date','Date','date',currentPlanDay(),'required')+field('note','Memory','text','','required maxlength="1000"'),'Save memory')}${d.journal.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="row"><span>${e(x.date)} · ${e(x.note)}</span>${btn('remove:journal:'+x.id,'×')}</div>`).join('')||'<p>No memories yet.</p>'}</section>`}
const icsEscape=x=>String(x).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\r/g,'');
function calendarExport(){let t=trip(),d=data(),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Park Day//Trip Planner//EN','CALSCALE:GREGORIAN','X-WR-CALNAME:'+icsEscape(t.name)];for(let x of d.plans)lines.push('BEGIN:VEVENT','UID:'+icsEscape(x.id)+'@parkday','DTSTAMP:'+stamp,'DTSTART:'+x.date.replaceAll('-','')+'T'+(x.time||'09:00').replace(':','')+'00','SUMMARY:'+icsEscape(x.name),'LOCATION:'+icsEscape(x.park),'DESCRIPTION:'+icsEscape(x.note||''),'END:VEVENT');for(let x of d.milestones.filter(x=>!x.done))lines.push('BEGIN:VEVENT','UID:'+icsEscape(x.id)+'@parkday','DTSTAMP:'+stamp,'DTSTART;VALUE=DATE:'+x.date.replaceAll('-',''),'SUMMARY:'+icsEscape(x.name),'BEGIN:VALARM','TRIGGER:-PT0M','ACTION:DISPLAY','DESCRIPTION:'+icsEscape(x.name),'END:VALARM','END:VEVENT');lines.push('END:VCALENDAR');downloadBlob(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),'park-day-itinerary.ics')}
function settings7(){return (embedded?baseSettings().replace(btn('import','Import existing trips (same origin)'),btn('originalTrips','Import preview trips in original Trips')):baseSettings()).replace('<section><h3>Native iOS roadmap</h3>',`<section><h3>Data and privacy</h3><p>V2.7 keeps trip, gallery and passport data on this device. The original GitHub Pages site is separate. Export backups regularly.</p>${btn('export','Export complete V2 backup')}<p class="muted">Backup restore and cross-device sync are not yet implemented. Calendar events export in local wall-clock time; check your calendar timezone.</p></section><section><h3>Native iOS roadmap</h3>`)}
function p7Click(b,op,x){let d=data();switch(op){case 'p7prev':case 'p7next':if(d){let days=dayRange(trip()),idx=days.indexOf(currentPlanDay())+(op==='p7prev'?-1:1);if(days[idx])planDay=days[idx];editPlanId='';render()}break;case 'p7editPlan':editPlanId=x;render();break;case 'p7cancelPlan':editPlanId='';render();break;case 'p7template':if(d){let day=currentPlanDay(),p=d.dayParks[day]||'Resort';if(!confirm('Add a sample day plan? Existing plans are kept.'))break;for(const [time,name,kind] of [['08:00','Breakfast','Dining'],['09:00','Explore '+p,'Activity'],['12:30','Lunch','Dining'],['15:00','Afternoon break','Break'],['18:30','Dinner','Dining']])if(!d.plans.some(z=>z.date===day&&z.time===time&&z.name===name))d.plans.push({id:id(),date:day,time,name,kind,park:p,note:'Sample plan',done:false});change()}break;case 'p7milestones':if(d){for(const [n,offset] of [['Review dining availability',-60],['Review transportation plans',-30],['Check packing list',-7],['Check resort arrival details',-1],['Check in / arrival day',0]])if(!d.milestones.some(z=>z.name===n))d.milestones.push({id:id(),name:n,date:dateAdd(trip().date,offset),done:false});change()}break;case 'p7calendar':if(d)calendarExport();break;case 'p7removeWalk':if(d){delete d.walking[x];change()}break;case 'p7discover':discoverParks();break;case 'p7schedule':loadSchedule();break;case 'p7catalog':loadCatalog();break;case 'p7fav':{let r=live[+x];if(r){let f=s.favorites[parkId]??=[];s.favorites[parkId]=f.includes(r.id)?f.filter(i=>i!==r.id):[...f,r.id];tell({kind:'park-favorite',parkId,rideId:r.id,on:s.favorites[parkId].includes(r.id)});change()}break}case 'p7reopen':{let r=live[+x];if(r&&!s.alerts.some(a=>a.ride===r.id&&a.type==='reopen')){s.alerts.push({ride:r.id,name:r.name,type:'reopen',hit:false});change()}break}case 'p7log':if(d&&live[+x])prepRide({name:live[+x].name,park:parkLabel()});break;case 'p7wishLog':{let r=d?.wish.find(z=>z.id===x);if(r)prepRide(r);break}case 'p7editRide':editingRide=x;rideDraft=null;render();break;case 'p7cancelRide':editingRide='';rideDraft=null;render();break;case 'p7share':if(d)shareRecap();break;case 'p7recapImage':if(d)recapImage().catch(err=>alert('Unable to create recap: '+err.message));break;default:return false}return true}
function p7Submit(a,v){let d=data(),t=trip();switch(a){case 'p7dayPark':if(d)d.dayParks[currentPlanDay()]=v.park;break;case 'p7plan':{if(!d||v.date<t.date||v.date>t.endDate){alert('Choose a day within your trip.');return true}let old=d.plans.find(x=>x.id===v.id),x={...v,id:old?.id||id(),done:old?.done||false};if(old)Object.assign(old,x);else d.plans.push(x);editPlanId='';planDay=v.date;break}case 'p7walk':if(!d||v.date<t.date||v.date>t.endDate||!Number.isFinite(Number(v.miles))||Number(v.miles)<0||Number(v.miles)>100){alert('Choose a valid trip day and mileage.');return true}d.walking[v.date]=Number(v.miles);break;case 'p7waitFilter':waitQuery=v.query.trim();waitSort=v.sort;waitFilter=v.filter;break;case 'p7passportFilter':passportPark=v.park;break;case 'p7ride':{if(!d||v.date<t.date||v.date>t.endDate){alert('Choose a valid trip day.');return true}let old=d.rides.find(x=>x.id===v.id),r={...v,id:old?.id||id(),wait:v.wait===''?null:Number(v.wait)};if(old)Object.assign(old,r);else d.rides.push(r);editingRide='';rideDraft=null;break}case 'p7wish':if(d&&!d.wish.some(x=>x.park===v.park&&x.name.toLowerCase()===v.name.trim().toLowerCase()))d.wish.push({id:id(),park:v.park,name:v.name.trim()});break;case 'p7compare':historyCompare=v.tripId;break;case 'p7journal':if(d)d.journal.push({...v,id:id()});break;default:return false}change();return true}

function miles(){return tripMiles(trip())}
function fetchWaits(){return fetchParkData()}
function originalDayParks(t,day){return (t?.days?.[day]?.parks||[]).map(k=>parkName(original.parks?.[k]?.name||s.parkDirectory?.[k]?.name||k))}
function syncOriginal(){original=read('parkCountdown.v1',{});walking=read('parkCountdown.v1.walk',{});if(!embedded)return;const existing=Array.isArray(s.trips)?s.trips:[];s.integratedIds??=[];s.legacyTrips??=existing.filter(t=>!(original.trips||[]).some(x=>x.id===t.id));const known=new Set(s.integratedIds);for(const t of original.trips||[])known.add(t.id);s.integratedIds=[...known];s.trips=(original.trips||[]).filter(t=>t.id&&t.date).map(t=>({...t,endDate:t.endDate||t.date}));s.favorites={...s.favorites,...(original.favs||{})};for(const [park,obs] of Object.entries(read('parkCountdown.v2.originalLive',{}))){for(const [ride,h] of Object.entries(obs.history||{})){const joined=[...(s.history[ride]||[]),...h].sort((a,b)=>a.at-b.at);s.history[ride]=joined.filter((x,i)=>!i||x.at-joined[i-1].at>=60000).slice(-72)}}if(!s.trips.some(t=>t.id===s.selected))s.selected=s.trips[0]?.id||''}
const screens={Home:dashboard,Trips:planner,Explore:explore,Waits:liveScreen,Passport:passport7,Memories:memories7,Settings:settings7};
function render(){let r=resort();document.documentElement.style.setProperty('--accent',r[3]);if(!screens[s.tab])s.tab='Home';$('#app').innerHTML=(error?`<section role="alert">${e(error)}</section>`:'')+screens[s.tab]?.();$('#nav').innerHTML=(embedded?tabs.filter(n=>n!=='Home'):tabs).map(n=>btn('tab:'+n,embedded?({Trips:'Planner',Explore:'Resorts',Waits:'Smart waits'}[n]||n):n,n===s.tab?'class="active" aria-current="page"':'')).join('');updateHero();if(embedded){tell({kind:'park-route',tab:s.tab,tripId:trip()?.id||''});document.querySelectorAll('a[href="'+originalURL+'"]').forEach(a=>{a.href='./';a.target='_top'});tell({kind:'park-height',height:Math.ceil(document.body.getBoundingClientRect().height)+8})}}
function change(){save();render()}
document.addEventListener('change',ev=>{let el=ev.target;if(el.name==='p7day'){planDay=el.value;editPlanId='';render();return}if(el.name==='p7park'){choosePark(el.value);return}if(el.name==='trip'){s.selected=el.value;planDay='';editPlanId='';editingRide='';rideDraft=null;historyCompare='';change()}if(el.name==='parkId'){parkId=el.value;live=[];fetchWaits()}if(el.dataset.toggle){let [arr,i]=el.dataset.toggle.split(':');let x=arr==='checks'?data()[arr][+i]:data()[arr].find(x=>x.id===i);if(x){x.done=el.checked;change()}}});
document.addEventListener('click',async ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.p7Trip){s.selected=b.dataset.p7Trip;historyCompare='';planDay='';editingRide='';rideDraft=null;change();return}if(b.dataset.p7CatalogPark){let p=b.dataset.p7CatalogPark,r=s.catalog[p]?.[+b.dataset.p7CatalogI];if(r&&trip())prepRide({name:r.name,park:p});return}if(b.dataset.imageRemove){delete s.images[b.dataset.imageRemove];change();return}let a=b.dataset.action;if(!a)return;let [op,x,y]=a.split(':');if(embedded&&op==='originalTrips'){tell({kind:'park-original',tab:'trips'});return}if(embedded&&op==='originalDay'){tell({kind:'park-original',tab:'home',day:currentPlanDay(),tripId:trip()?.id});return}if(embedded&&op==='import'){tell({kind:'park-original',tab:'trips'});return}if(op.startsWith('p7')&&p7Click(b,op,x))return;if(op==='heroPrev'||op==='heroNext'){let n=galleryFor(resort()).length||1;heroIndex=(heroIndex+(op==='heroPrev'?-1:1)+n)%n;updateHero()}else if(op==='detail'){resortDetail=+x;render();window.scrollTo(0,0)}else if(op==='detailClose'){resortDetail=-1;render()}else if(op==='clearFilter'){resortFilter='All';resortSearch='';render()}else if(op==='galleryRemove'){let r=resorts[+x],list=gallery(r).slice();list.splice(+y,1);s.gallery[r[0]]=list;delete s.images[r[0]];change()}else if(op==='galleryExport'){downloadJSON({format:'park-day-resort-pack-v1',resorts:Object.fromEntries(resorts.map(r=>[r[0],gallery(r)]).filter(([,v])=>v.length))},'resort-picture-pack.json')}else if(op==='tab'){s.tab=x;change();if(x==='Waits'&&!liveAt&&parkId)fetchWaits()}else if(op==='resort'){data().resort=resorts[+x][0];change()}else if(op==='remove'){let arr=data()[x];data()[x]=arr.filter((v,i)=>x==='checks'?i!==+y:v.id!==y);change()}else if(op==='refresh')fetchWaits();else if(op==='alertRemove'){s.alerts.splice(+x,1);change()}else if(op==='notify'){if(!globalThis.Notification){alert('Browser notifications are unavailable. In-app thresholds still work.');return}try{await Notification.requestPermission()}catch{alert('Notification permission is unavailable.')}}else if(op==='logLive'){let v=live[+x];if(v&&trip()){data().rides.push({id:id(),name:v.name,park:original.parks?.[parkId]?.name||'Other',wait:0,date:today()});change();alert('Ride logged. Actual wait defaults to zero for this draft.')}}else if(op==='import'){importTrips();render()}else if(op==='export'){let blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='park-day-v2-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(op==='share'){let d=data(),txt=`${trip().name}: ${d.rides.length} rides, ${miles()} miles walked, ${d.rides.reduce((a,x)=>a+x.wait,0)} queue minutes.`;try{if(navigator.share)await navigator.share({text:txt});else if(navigator.clipboard)await navigator.clipboard.writeText(txt);else alert(txt)}catch{}}});
document.addEventListener('submit',async ev=>{let f=ev.target;if(!f.dataset.form)return;ev.preventDefault();let v=Object.fromEntries(new FormData(f)),d=data(),a=f.dataset.form;if(a.startsWith('p7')&&p7Submit(a,v))return;switch(a){case 'integratedPrefs':if(d){d.resort=v.resort;d.mode=v.mode}break;case 'resortSearch':resortSearch=v.query.trim();resortFilter=v.category;resortDetail=-1;render();return;case 'galleryPrefs':s.galleryPrefs={theme:v.theme,rotation:v.rotation==='on'};heroIndex=0;break;case 'galleryUpload':{let r=resorts.find(r=>r[0]===v.resort);if(!r)return;let old=s.gallery[r[0]],list=gallery(r).slice();try{let files=Array.from(f.elements.photos.files);if(list.length+files.length>8)throw Error('Up to eight photos per resort. Remove some first.');for(let file of files)list.push({src:await resizePhoto(file),kind:v.kind,name:file.name});s.gallery[r[0]]=list;if(!save()){if(old)s.gallery[r[0]]=old;else delete s.gallery[r[0]];render();return}}catch(err){alert(err.message);return}break}case 'galleryImport':{try{if(v.pack.size>12000000)throw Error('Picture pack is too large.');let pack=JSON.parse(await v.pack.text());if(pack.format!=='park-day-resort-pack-v1'||!pack.resorts||typeof pack.resorts!=='object')throw Error('Invalid picture pack.');let next={...s.gallery};for(let r of resorts){let incoming=pack.resorts[r[0]];if(incoming===undefined)continue;if(!Array.isArray(incoming)||incoming.some(x=>!x||!safePhoto(x.src)||x.src.length>1500000||!['any','day','night'].includes(x.kind)))throw Error('Invalid photo in '+r[0]);let list=gallery(r).slice();for(let x of incoming)if(!list.some(y=>y.src===x.src))list.push({src:x.src,kind:x.kind,name:String(x.name||'Imported photo').slice(0,120)});if(list.length>8)throw Error('Too many photos for '+r[0]);next[r[0]]=list}let old=s.gallery;s.gallery=next;if(!save()){s.gallery=old;render();return}}catch(err){alert(err.message);return}break}case 'newTrip':case 'editTrip':if(embedded){tell({kind:'park-original',tab:'trips'});return}if(v.end<v.date){alert('Departure cannot be before arrival.');return}if(a==='newTrip'){let t={id:id(),name:v.name,date:v.date,endDate:v.end,time:v.time,tz:'America/New_York'};s.trips.push(t);s.selected=t.id}else{Object.assign(trip(),{name:v.name,date:v.date,endDate:v.end,time:v.time,tz:trip().tz||'America/New_York'});d.resort=v.resort;d.mode=v.mode}break;case 'plan':d.plans.push({...v,id:id()});break;case 'milestone':d.milestones.push({...v,id:id(),done:false});break;case 'check':d.checks.push({name:v.name,done:false});break;case 'budget':d.budget=Number(v.budget);break;case 'expense':d.expenses.push({id:id(),name:v.name,amount:Number(v.amount)});break;case 'ride':d.rides.push({...v,id:id(),date:today(),wait:Number(v.wait)});break;case 'journal':d.journal.push({...v,id:id()});break;case 'parkId':parkId=v.id.trim();live=[];await fetchWaits();return;case 'alert':s.alerts=s.alerts.filter(x=>x.ride!==v.ride||x.type==='reopen');s.alerts.push({...v,type:'threshold',limit:Number(v.limit),hit:false});break;case 'image':if(!['image/jpeg','image/png','image/webp'].includes(v.image.type)||v.image.size>1000000){alert('Choose a JPEG, PNG or WebP under 1 MB.');return}let previous=s.images[v.resort];let photo=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(v.image)}).catch(()=>null);if(!photo)return;s.images[v.resort]=photo;if(!save()){if(previous)s.images[v.resort]=previous;else delete s.images[v.resort];render();return}break}change()});
if(embedded){syncOriginal();s.tab=new URLSearchParams(location.search).get('tab')||'Explore';if(!screens[s.tab]||s.tab==='Home')s.tab='Explore';window.addEventListener('message',ev=>{if(ev.origin!==location.origin||ev.source!==window.parent)return;let m=ev.data||{};if(m.kind==='park-open'){syncOriginal();if(s.trips.some(t=>t.id===m.tripId))s.selected=m.tripId;if(m.day&&dayRange(trip()).includes(m.day))planDay=m.day;else planDay='';editPlanId='';if(screens[m.tab])s.tab=m.tab;render();if(s.tab==='Waits'&&!liveAt&&parkId)fetchWaits()}else if(m.kind==='park-refresh'){syncOriginal();render()}});window.addEventListener('storage',ev=>{if(ev.key==='parkCountdown.v1.walk')walking=read(ev.key,{});});if(globalThis.ResizeObserver)new ResizeObserver(()=>tell({kind:'park-height',height:Math.ceil(document.body.getBoundingClientRect().height)+8})).observe(document.body);tell({kind:'park-ready'});}
render();setInterval(()=>{if(s.galleryPrefs.rotation&&s.tab==='Home'){heroIndex++;updateHero()}},15000);setInterval(()=>{if($('#count'))$('#count').innerHTML=count().map((v,i)=>stat(String(v).padStart(2,'0'),['DAYS','HRS','MIN','SEC'][i])).join('')},1000);setInterval(()=>{if(parkId&&!document.hidden&&(s.tab==='Waits'||(s.tab==='Home'&&liveAt)))fetchWaits()},300000);if(!embedded&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
